// Process and structure data for Google Sheets logging
const agentResults = $input.all();
const timestamp = new Date();

// Initialize default values
let processedData = {
  date: timestamp.toISOString().split('T')[0],
  time: timestamp.toTimeString().split(' ')[0],
  totalEmails: 0,
  deleted: 0,
  categorized: 0,
  archived: 0,
  emailDetails: 'No emails processed',
  workflowId: `${$workflow.id}-${$execution.id}`
};

// Process agent results if available
if (agentResults && agentResults.length > 0) {
  agentResults.forEach(result => {
    if (result.json) {
      let agentData = {};

      try {
        // Try to parse agent output
        if (result.json.output) {
          // Extract JSON from text response
          const outputText = result.json.output;
          const jsonStart = outputText.indexOf('{');
          const jsonEnd = outputText.lastIndexOf('}') + 1;

          if (jsonStart !== -1 && jsonEnd > jsonStart) {
            const jsonString = outputText.substring(jsonStart, jsonEnd);
            agentData = JSON.parse(jsonString);
          }
        } else {
          agentData = result.json;
        }

        // Extract summary data
        if (agentData.summary) {
          processedData.totalEmails = agentData.summary.total || 0;
          processedData.deleted = agentData.summary.deleted || 0;
          processedData.categorized = agentData.summary.categorized || 0;
          processedData.archived = agentData.summary.archived || 0;
        }

        // Extract email details
        if (agentData.emails_processed && Array.isArray(agentData.emails_processed)) {
          const emailSummaries = agentData.emails_processed.map(email => {
            return {
              subject: (email.subject || 'No Subject').substring(0, 50),
              action: email.action_taken || 'unknown',
              reasoning: (email.reasoning || 'No reason').substring(0, 100)
            };
          });

          processedData.emailDetails = JSON.stringify(emailSummaries);

          // Update totals if summary not available
          if (!agentData.summary) {
            processedData.totalEmails = emailSummaries.length;
            processedData.deleted = emailSummaries.filter(e => e.action === 'deleted').length;
            processedData.categorized = emailSummaries.filter(e => e.action === 'categorized').length;
            processedData.archived = emailSummaries.filter(e => e.action === 'archived').length;
          }
        }

      } catch (error) {
        console.log('Error parsing agent data:', error.message);
        processedData.emailDetails = `Error: ${error.message}`;
      }
    }
  });
}

// Log the structured data
console.log('📊 Structured data for Google Sheets:');
console.log(`📅 Date: ${processedData.date}`);
console.log(`⏰ Time: ${processedData.time}`);
console.log(`📧 Total: ${processedData.totalEmails}`);
console.log(`🗑️ Deleted: ${processedData.deleted}`);
console.log(`🏷️ Categorized: ${processedData.categorized}`);
console.log(`📦 Archived: ${processedData.archived}`);

// Return structured data for Google Sheets
return {
  Date: processedData.date,
  Time: processedData.time,
  Total_Emails: processedData.totalEmails,
  Deleted: processedData.deleted,
  Categorized: processedData.categorized,
  Archived: processedData.archived,
  Email_Details: processedData.emailDetails,
  Workflow_ID: processedData.workflowId
};
